for (const [id, s] of S6) STATUS[id] = s;
for (const [id, s] of S6work) WORK_STATUS[id] = s;
for (const [id, s] of S7) STATUS[id] = s;
for (const [id, s] of S7work) WORK_STATUS[id] = s;

for (const [id, s] of Object.entries(STATUS)) {
  if (!STATUSES.includes(s.status)) throw new Error(`${id}: unknown status ${s.status}`);
  if (!BATCHES[s.batch]) throw new Error(`${id}: batch ${s.batch} has no BATCHES entry`);
}
